const __pageData = JSON.parse('{"title":"第 2 章：张量与自动求导","description":"数字怎样排成张量，形状怎么读；loss.backward() 怎样沿计算图算出每个参数的梯度。","frontmatter":{"title":"第 2 章：张量与自动求导","description":"数字怎样排成张量，形状怎么读；loss.backward() 怎样沿计算图算出每个参数的梯度。","pageClass":"tinyllm-course"},"headers":[],"relativePath":"tinyllm/tensors-and-autograd.md","filePath":"tinyllm/tensors-and-autograd.md"}');
